import { test } from 'node:test';
import assert from 'node:assert/strict';
import { criarPipeline } from './solution.mjs';

test('executa os middlewares na ordem da lista', () => {
  const contexto = { ordem: [] };
  const executar = criarPipeline([
    (ctx, next) => { ctx.ordem.push('autenticar'); next(); },
    (ctx, next) => { ctx.ordem.push('validar'); next(); },
    (ctx, next) => { ctx.ordem.push('responder'); next(); },
  ]);
  executar(contexto);
  assert.deepEqual(contexto.ordem, ['autenticar', 'validar', 'responder']);
});

test('o contexto é compartilhado: uma etapa enxerga o que a anterior fez', () => {
  const executar = criarPipeline([
    (ctx, next) => { ctx.usuario = 'Ana'; next(); },
    (ctx, next) => { ctx.saudacao = `Olá, ${ctx.usuario}!`; next(); },
  ]);
  const contexto = executar({});
  assert.equal(contexto.saudacao, 'Olá, Ana!');
});

test('um middleware pode interromper a cadeia sem chamar next', () => {
  const contexto = { passou: [] };
  const executar = criarPipeline([
    (ctx, next) => { ctx.passou.push('autorizar'); next(); },
    (ctx) => { ctx.passou.push('bloqueado'); }, // não chama next: encerra aqui
    (ctx) => { ctx.passou.push('nunca chega'); },
  ]);
  executar(contexto);
  assert.deepEqual(contexto.passou, ['autorizar', 'bloqueado']);
});

test('validação: não-lista lança na criação e erro de middleware propaga', () => {
  assert.throws(() => criarPipeline('não é lista'));
  const executar = criarPipeline([
    () => { throw new Error('falhou na etapa'); },
  ]);
  assert.throws(() => executar({}), /falhou na etapa/);
});

solutionCode:
// O padrão middleware: cada etapa recebe o contexto e um `next` para
// continuar a cadeia — uma etapa pode interromper o fluxo ou encurtar a cadeia.
export function criarPipeline(middlewares) {
  if (!Array.isArray(middlewares)) {
    throw new Error('middlewares precisa ser uma lista');
  }

  return function executar(contexto) {
    let indice = -1;
    const next = () => {
      indice += 1;
      if (indice < middlewares.length) {
        // A etapa atual decide se chama next() (continua) ou não (interrompe).
        return middlewares[indice](contexto, next);
      }
    };
    next();
    return contexto; // o contexto final reflete tudo o que as etapas fizeram
  };
}
